using BiolaCampus.Core;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace BiolaCampus.World
{
    /// <summary>
    /// URP quality presets + post-processing. Pipeline assets are generated by Biola ▸ Setup Project
    /// into Resources/BiolaURP (Low / Medium / High share one renderer with an SSAO feature).
    ///
    ///   Low    : no shadows, no SSAO, no bloom, FXAA, render scale 0.85
    ///   Medium : soft sun shadows (2 cascades, 160 m), bloom, ACES, grading, fog, FXAA   (Web default)
    ///   High   : 4 cascades (320 m, 4096), SSAO, bloom, SMAA, more lamp lights          (desktop default)
    /// </summary>
    public class RenderingSetup : MonoBehaviour
    {
        public static RenderingSetup Instance { get; private set; }

        Camera _camera;
        Volume _volume;
        Bloom _bloom;
        Tonemapping _tonemap;
        ColorAdjustments _grade;
        WhiteBalance _white;
        Vignette _vignette;
        UniversalRendererData _renderer;

        public bool IsUrp => GraphicsSettings.currentRenderPipeline is UniversalRenderPipelineAsset;

        public void Initialize(Camera cam)
        {
            Instance = this;
            _camera = cam;
            _renderer = Resources.Load<UniversalRendererData>("BiolaURP/BiolaRenderer");

            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
            _tonemap = profile.Add<Tonemapping>(true);
            _tonemap.mode.Override(TonemappingMode.ACES);
            _bloom = profile.Add<Bloom>(true);
            _bloom.threshold.Override(1.05f);
            _bloom.intensity.Override(0.45f);
            _bloom.scatter.Override(0.65f);
            _bloom.highQualityFiltering.Override(false);
            _grade = profile.Add<ColorAdjustments>(true);
            _white = profile.Add<WhiteBalance>(true);
            _vignette = profile.Add<Vignette>(true);
            _vignette.intensity.Override(0.18f);
            _vignette.smoothness.Override(0.45f);

            var go = new GameObject("Post-processing Volume");
            go.transform.SetParent(transform, false);
            _volume = go.AddComponent<Volume>();
            _volume.isGlobal = true;
            _volume.priority = 10f;
            _volume.sharedProfile = profile;

            GameSettings.Changed += Apply;
            SunController.NightChanged += _ => ApplyGrade();
            Apply();
        }

        void OnDestroy() => GameSettings.Changed -= Apply;

        TileQuality? _applied;

        public void Apply()
        {
            var q = GameSettings.Quality;
            if (_applied != q)
            {
                _applied = q;
                var asset = Resources.Load<UniversalRenderPipelineAsset>("BiolaURP/URP_" + q);
                if (asset != null) QualitySettings.renderPipeline = asset;
                if (_renderer != null)
                    foreach (var f in _renderer.rendererFeatures)
                        if (f != null && f.GetType().Name.Contains("AmbientOcclusion")) f.SetActive(q == TileQuality.High);
            }

            if (_camera != null)
            {
                var data = _camera.GetUniversalAdditionalCameraData();
                data.renderPostProcessing = true;   // ACES tonemapping on every preset keeps colours consistent
                data.antialiasing = q == TileQuality.High ? AntialiasingMode.SubpixelMorphologicalAntiAliasing : AntialiasingMode.FastApproximateAntialiasing;
                data.antialiasingQuality = AntialiasingQuality.Medium;
                data.dithering = true;
                data.renderShadows = q != TileQuality.Low;
                _camera.allowHDR = true;
            }
            _bloom.active = q != TileQuality.Low;
            _vignette.active = q != TileQuality.Low;

            RenderSettings.fog = true;
            RenderSettings.fogMode = FogMode.ExponentialSquared;
            ApplyGrade();
        }

        void ApplyGrade()
        {
            bool night = SunController.Instance != null && SunController.Instance.IsNight;
            if (night)
            {
                _grade.postExposure.Override(0.35f);
                _grade.contrast.Override(14f);
                _grade.saturation.Override(-12f);
                _white.temperature.Override(-18f);
                _bloom.intensity.Override(1.1f);
                _bloom.threshold.Override(0.9f);
                RenderSettings.fogDensity = 0.0012f;
            }
            else
            {
                _grade.postExposure.Override(0.1f);
                _grade.contrast.Override(10f);
                _grade.saturation.Override(10f);
                _white.temperature.Override(6f);
                _bloom.intensity.Override(0.45f);
                _bloom.threshold.Override(1.05f);
                // Light haze that blends our campus into the Google tiles beyond (~2 km visibility).
                RenderSettings.fogDensity = GameSettings.Quality == TileQuality.Low ? 0.0011f : 0.0008f;
            }
        }
    }
}
